#!/usr/bin/env python3
# vokra Python bindings — ctypes declaration codegen.
#
# Copyright The Vokra Authors.
# SPDX-License-Identifier: Apache-2.0
#
# Parses `include/vokra.h` (itself auto-generated by cbindgen from `vokra-capi`)
# and emits `bindings/python/src/vokra/_bindings.py` containing:
#   - every C enum constant
#   - every concrete POD struct as a ctypes.Structure
#   - every opaque struct handle as ctypes.c_void_p
#   - a `bind(lib)` helper that sets argtypes/restype on every exported
#     function so ctypes marshals arguments correctly (T07).
#
# The generator is intentionally minimal: it treats vokra.h as a *pinned*
# surface (cbindgen output is deterministic; the drift check runs
# `scripts/gen-c-abi.sh --check` upstream). This script's own drift is caught
# by `check-py-bindings.sh --check` (compare emitted file byte-for-byte).
#
# Zero non-stdlib deps (NFR-DS-02): only re / pathlib / argparse / sys / os /
# difflib.

from __future__ import annotations

import argparse
import difflib
import re
import sys
from pathlib import Path
from typing import List, Sequence, Tuple

REPO_ROOT = Path(__file__).resolve().parents[3]
HEADER = REPO_ROOT / "include" / "vokra.h"
OUT = REPO_ROOT / "bindings" / "python" / "src" / "vokra" / "_bindings.py"

# --- C -> ctypes type map (only the primitive types that appear in vokra.h) ---
# `void` is handled as restype=None; opaque struct pointers are handled below.
PRIM_TYPES = {
    "void": "None",
    "bool": "ctypes.c_bool",
    "char": "ctypes.c_char",
    "int32_t": "ctypes.c_int32",
    "int64_t": "ctypes.c_int64",
    "uint8_t": "ctypes.c_uint8",
    "uint32_t": "ctypes.c_uint32",
    "uint64_t": "ctypes.c_uint64",
    "size_t": "ctypes.c_size_t",
    "float": "ctypes.c_float",
    "double": "ctypes.c_double",
}

def strip_comments(src: str) -> str:
    """Remove /* ... */ and // ... comments so regexes see only code."""
    src = re.sub(r"/\*.*?\*/", "", src, flags=re.DOTALL)
    src = re.sub(r"//[^\n]*", "", src)
    return src


def parse_enum(src: str, name: str) -> List[Tuple[str, int]]:
    """Extract `name` enum variants as (identifier, value) pairs."""
    m = re.search(
        r"typedef\s+enum\s+" + re.escape(name) + r"\s*\{([^}]*)\}\s*" + re.escape(name) + r"\s*;",
        src,
        re.DOTALL,
    )
    if not m:
        raise SystemExit(f"gen-py-bindings: enum {name} not found in {HEADER}")
    body = m.group(1)
    variants: List[Tuple[str, int]] = []
    next_val = 0
    for raw in body.split(","):
        line = raw.strip()
        if not line:
            continue
        if "=" in line:
            ident, val = line.split("=", 1)
            variants.append((ident.strip(), int(val.strip(), 0)))
            next_val = variants[-1][1] + 1
        else:
            variants.append((line, next_val))
            next_val += 1
    return variants


def parse_enums(src: str) -> List[Tuple[str, List[Tuple[str, int]]]]:
    """Return every ``typedef enum`` in source order."""
    names = re.findall(r"typedef\s+enum\s+(\w+)\s*\{", src)
    return [(name, parse_enum(src, name)) for name in names]


def _split_typed_name(decl: str, *, what: str) -> Tuple[str, str]:
    """Split ``const struct foo *value`` into its type and identifier."""
    match = re.match(r"(?P<type>.+?)(?P<ident>\w+)\s*$", decl.strip(), re.DOTALL)
    if not match:
        raise SystemExit(f"gen-py-bindings: cannot parse {what} {decl!r}")
    return match.group("type").strip(), match.group("ident")


def parse_structs(src: str) -> List[Tuple[str, List[Tuple[str, str]]]]:
    """Return concrete ``typedef struct`` definitions in source order."""
    pattern = re.compile(
        r"typedef\s+struct\s+(?P<name>\w+)\s*\{(?P<body>.*?)\}\s*(?P=name)\s*;",
        re.DOTALL,
    )
    structs: List[Tuple[str, List[Tuple[str, str]]]] = []
    for match in pattern.finditer(src):
        fields: List[Tuple[str, str]] = []
        for raw in match.group("body").split(";"):
            raw = raw.strip()
            if not raw:
                continue
            field_type, field_name = _split_typed_name(raw, what="struct field")
            fields.append((field_name, field_type))
        structs.append((match.group("name"), fields))
    return structs


def parse_opaque_structs(src: str) -> List[str]:
    """Return forward-declared opaque struct typedefs in source order."""
    return re.findall(r"typedef\s+struct\s+(\w+)\s+\1\s*;", src)


def discover_function_names(src: str) -> List[str]:
    """Broadly discover every file-scope-looking ``vokra_*`` declaration.

    This scanner deliberately ignores return and argument types. Its only job
    is to make ``parse_functions`` coverage measurable: if a future C syntax
    shape falls outside the typed parser, generation fails instead of silently
    emitting a smaller table.
    """
    return re.findall(r"\b(vokra_\w+)\s*\([^;{}]*\)\s*;", src, re.DOTALL)


def map_c_type(
    c: str,
    *,
    opaque: Sequence[str] = (),
    structs: Sequence[str] = (),
    enums: Sequence[str] = (),
) -> str:
    """Map a C type expression (possibly with pointers) to a ctypes expression."""
    c = c.strip()
    is_const = "const" in c.split()
    # Peel pointer levels.
    ptrs = 0
    while c.endswith("*"):
        ptrs += 1
        c = c[:-1].strip()
    # Drop `const` / `struct` / `enum` qualifiers.
    parts = [p for p in c.split() if p not in ("const", "struct", "enum")]
    base = " ".join(parts) if parts else "void"

    if base in opaque:
        # Opaque handle: `T*` -> c_void_p, `T**` -> POINTER(c_void_p).
        inner = "ctypes.c_void_p"
        ptrs -= 1  # the T itself is the void* handle
        if ptrs < 0:
            raise SystemExit(f"gen-py-bindings: opaque {base} used by value")
    elif base in structs:
        inner = base
    elif base in enums:
        # C enums are int-sized on all our targets.
        inner = "ctypes.c_int"
    elif base in PRIM_TYPES:
        inner = PRIM_TYPES[base]
    else:
        raise SystemExit(f"gen-py-bindings: unmapped C type {base!r}")

    if base == "char" and ptrs >= 1:
        if ptrs == 1 and not is_const:
            # Mutable `char *` is an output/freeable byte pointer, not an
            # immutable Python bytes string. Leave one pointer level in place.
            inner = "ctypes.c_char"
        else:
            # `const char *` -> c_char_p; `char **` -> POINTER(c_char_p).
            inner = "ctypes.c_char_p"
            ptrs -= 1

    for _ in range(ptrs):
        inner = f"ctypes.POINTER({inner})"
    return inner


def parse_functions(src: str) -> List[Tuple[str, str, List[str]]]:
    """Return [(name, restype_c, [argtype_c, ...]), ...]."""
    fns: List[Tuple[str, str, List[str]]] = []
    # The return grammar is deliberately broader than a fixed allow-list: this
    # recognises plain scalars, enum/struct returns, qualifiers, and pointers.
    # ``map_c_type`` remains the fail-closed type gate, so a newly recognised
    # declaration with an unsupported type fails instead of disappearing.
    pattern = re.compile(
        r"^(?P<ret>(?:(?:const|struct|enum)\s+)*\w+(?:\s*\*)*)\s*"
        r"(?P<name>vokra_\w+)\s*\((?P<args>[^)]*)\)\s*;",
        re.DOTALL | re.MULTILINE,
    )
    for m in pattern.finditer(src):
        name = m.group("name")
        ret = m.group("ret").strip()
        args_raw = m.group("args").strip()
        args: List[str] = []
        if args_raw and args_raw != "void":
            for a in args_raw.split(","):
                a = a.strip()
                arg_type, _ = _split_typed_name(a, what="argument")
                args.append(arg_type)
        fns.append((name, ret, args))
    return fns


TEMPLATE_HEADER = '''# SPDX-License-Identifier: Apache-2.0
# !!! AUTO-GENERATED by bindings/python/scripts/gen-py-bindings.py — DO NOT EDIT. !!!
# Regenerate with `uv run --no-project --python 3.12 python bindings/python/scripts/gen-py-bindings.py`;
# CI enforces drift via `bindings/python/scripts/check-py-bindings.sh --check`.
#
# Source of truth: include/vokra.h (itself cbindgen output from `vokra-capi`).
# This file declares ctypes argtypes/restype so the pure-Python wrapper (T08+)
# can marshal calls into the prebuilt libvokra native library without any
# non-stdlib deps (NFR-DS-02).

from __future__ import annotations

import ctypes

# --- Enum constants (vokra_status_t) ---------------------------------------
'''


def emit(header_src: str) -> str:
    src = strip_comments(header_src)
    enum_defs = parse_enums(src)
    struct_defs = parse_structs(src)
    opaque_defs = parse_opaque_structs(src)
    enum_names = [name for name, _ in enum_defs]
    struct_names = [name for name, _ in struct_defs]
    fns = parse_functions(src)
    fn_names = [name for name, _, _ in fns]
    declared_names = discover_function_names(src)
    if fn_names != declared_names:
        missing = [name for name in declared_names if name not in fn_names]
        extra = [name for name in fn_names if name not in declared_names]
        raise SystemExit(
            "gen-py-bindings: function parser coverage mismatch "
            f"(missing={missing!r}, extra={extra!r})"
        )
    if not fns:
        raise SystemExit("gen-py-bindings: no vokra_* function declarations found")
    if len(fn_names) != len(set(fn_names)):
        raise SystemExit("gen-py-bindings: duplicate vokra_* function declaration")

    out = [TEMPLATE_HEADER]
    for index, (enum_name, variants) in enumerate(enum_defs):
        if index:
            out.append(f"\n# --- Enum constants ({enum_name}) " + "-" * 24 + "\n")
        for ident, val in variants:
            out.append(f"{ident} = {val}\n")

    out.append("\n# --- Structures ------------------------------------------------------------\n")
    for struct_name, fields in struct_defs:
        out.append(f"class {struct_name}(ctypes.Structure):\n")
        out.append("    _fields_ = [\n")
        for field_name, field_type in fields:
            mapped = map_c_type(
                field_type,
                opaque=opaque_defs,
                structs=struct_names,
                enums=enum_names,
            )
            out.append(f"        ({field_name!r}, {mapped}),\n")
        out.append("    ]\n\n")

    out.append(
        "# Opaque handles. Python never dereferences these pointers; only the\n"
        "# native runtime owns their layouts.\n"
    )
    for opaque_name in opaque_defs:
        out.append(f"{opaque_name} = ctypes.c_void_p\n")
    if "vokra_session_t" in opaque_defs:
        out.append("VokraSession = vokra_session_t\n")
    if "vokra_stream_t" in opaque_defs:
        out.append("VokraStream = vokra_stream_t\n")

    out.append(
        "\n# --- ctypes prototypes -----------------------------------------------------\n"
        "# Populated by `bind(lib)` at import time from the loaded CDLL.\n"
        "\n"
        "PROTOTYPES = {\n"
    )
    for name, ret, args in fns:
        map_kwargs = {
            "opaque": opaque_defs,
            "structs": struct_names,
            "enums": enum_names,
        }
        ret_py = map_c_type(ret, **map_kwargs)
        arg_py = ", ".join(map_c_type(a, **map_kwargs) for a in args) if args else ""
        out.append(f"    {name!r}: (\n")
        out.append(f"        {ret_py},\n")
        out.append(f"        ({arg_py},),\n" if arg_py else "        (),\n")
        out.append("    ),\n")
    out.append("}\n")

    out.append(
        "\n\n"
        "def bind(lib: ctypes.CDLL) -> ctypes.CDLL:\n"
        "    \"\"\"Attach argtypes/restype to every exported vokra_* function on `lib`.\n"
        "\n"
        "    Safe to call multiple times (idempotent). Raises AttributeError if the\n"
        "    loaded library is missing a symbol the header declares — this signals a\n"
        "    binding/library version skew and MUST fail loudly (FR-EX-08: no silent\n"
        "    fallback).\n"
        "    \"\"\"\n"
        "    for name, (restype, argtypes) in PROTOTYPES.items():\n"
        "        fn = getattr(lib, name)\n"
        "        fn.restype = restype\n"
        "        fn.argtypes = list(argtypes)\n"
        "    return lib\n"
    )
    return "".join(out)


def main() -> int:
    ap = argparse.ArgumentParser(description="Generate Vokra Python ctypes bindings.")
    ap.add_argument(
        "--check",
        action="store_true",
        help="Fail (exit 1) if the on-disk _bindings.py differs from the generator output.",
    )
    ap.add_argument(
        "--header",
        default=str(HEADER),
        help=f"Path to vokra.h (default: {HEADER}).",
    )
    ap.add_argument(
        "--out",
        default=str(OUT),
        help=f"Path to emitted _bindings.py (default: {OUT}).",
    )
    args = ap.parse_args()

    header_path = Path(args.header)
    out_path = Path(args.out)

    if not header_path.exists():
        print(f"gen-py-bindings: header not found: {header_path}", file=sys.stderr)
        return 2
    generated = emit(header_path.read_text(encoding="utf-8"))

    if args.check:
        if not out_path.exists():
            print(
                f"gen-py-bindings --check: {out_path} does not exist; run without --check to create it.",
                file=sys.stderr,
            )
            return 1
        current = out_path.read_text(encoding="utf-8")
        if current != generated:
            print(f"gen-py-bindings --check: DRIFT — {out_path} is stale.", file=sys.stderr)
            diff = difflib.unified_diff(
                current.splitlines(keepends=True),
                generated.splitlines(keepends=True),
                fromfile=str(out_path),
                tofile="<generated>",
            )
            sys.stderr.writelines(diff)
            return 1
        return 0

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(generated, encoding="utf-8")
    print(f"gen-py-bindings: wrote {out_path} ({len(generated)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
